#include <iostream>
#include <vector>
#include <memory>

class Estoque {
private:
    // Vetor seguro encapsulado gerenciando objetos polimórficos
    std::vector<double> totais;
public:
    void adicionar(double valor) { totais.push_back(valor); }
    double calcularTotal() const {
        double soma = 0;
        for (double v : totais) soma += v;
        return soma;
    }
};

int main() {
    Estoque loja;
    loja.adicionar(450.0); // 3 * 150.0 (Teclados)
    loja.adicionar(400.0); // 5 * 80.0 (Mouses)
    std::cout << "Valor total no estoque: R$ " << loja.calcularTotal() << "\n"; // 850.0
    return 0;
}

